svg.script:
(function () {
  const provincias = document.querySelectorAll('.provincia-mapa');

  provincias.forEach(function (provincia) {
    provincia.setAttribute('role', 'button');
    provincia.setAttribute('tabindex', '0');
    provincia.setAttribute(
      'aria-label',
      'Provincia de ' + (provincia.getAttribute('data-provincia') || '')
    );

    provincia.addEventListener('click', function (event) {
      event.stopPropagation();
      provincias.forEach(function (p) { p.classList.remove('selected'); });
      provincia.classList.add('selected');

      // Permite conectar fácilmente cada provincia con tu propia función.
      provincia.dispatchEvent(new CustomEvent('provinciaSeleccionada', {
        bubbles: true,
        detail: {
          id: provincia.id,
          provincia: provincia.getAttribute('data-provincia')
        }
      }));
    });

    provincia.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        provincia.click();
      }
    });
  });

  document.documentElement.addEventListener('click', function () {
    provincias.forEach(function (p) { p.classList.remove('selected'); });
  });
})();
